  static String _getMasterKey(String master) {
    final lower = master.toLowerCase();
    if (lower.contains('efren')) return 'efren';
    if (lower.contains('ronnie')) return 'ronnie';
    if (lower.contains('shane')) return 'shane';
    if (lower.contains('florian') || lower.contains('venom')) return 'venom';
    if (lower.contains('hoàng') || lower.contains('hoang')) return 'hoang';
    if (lower.contains('earl')) return 'earl';
    if (lower.contains('bustamante')) return 'bustamante';
    if (lower.contains('shaw')) return 'shaw';
    if (lower.contains('gorst')) return 'gorst';
    if (lower.contains('blomdahl')) return 'blomdahl';
    if (lower.contains('saygıner') || lower.contains('sayginer')) return 'sayginer';
    if (lower.contains('ceulemans')) return 'ceulemans';
    if (lower.contains('massey')) return 'massey';
    if (lower.contains('jeanette') || lower.contains('widow')) return 'jeanette';
    return '';
  }

  static String getMasterName(String master, String lang, {bool short = false}) {
    if (lang == 'vi') return master;
    final key = _getMasterKey(master);
    if (key.isEmpty) return master;
    if (short) {
      return masterShortNames[key]?[lang] ?? masterShortNames[key]?['en'] ?? master;
    }
    return masterNames[key]?[lang] ?? masterNames[key]?['en'] ?? master;
  }

  static String getNickname(String id, String lang, String defaultText) {
    if (lang == 'vi') return defaultText;
    final masterKey = id.split('_').first;
    return masterNicknames[masterKey]?[lang] ?? masterNicknames[masterKey]?['en'] ?? defaultText;
  }

