  static const Map<String, Map<String, String>> hints = {
    'efren_kick_escape': {'en': 'Aim off short rail with 55% power, slight left English to open rebound angle accurately into ball 1.', 'zh': '瞄准短边库边，力度55%，微加左塞，使母球以精确的张角反弹撞击1号球。', 'ja': '短レールを55%の力で狙い、わずかに左ひねりを効かせて1番球へ正確に角度を開こう。', 'ko': '55%의 힘으로 단쿠션을 노리고, 약간의 좌측 회전을 주어 1번 볼을 향해 반사각을 정확히 벌리세요.'},
    'efren_rail_cut_master': {'en': 'Contact only 1/16th edge of ball 9, with feather-light draw to hold cue ball safely on rail.', 'zh': '仅触碰9号球外缘1/16厚度，配合极轻微低杆回拉确保母球安全停靠。', 'ja': '9番球のエッジ1/16だけを捉え、ごく軽い引きで手玉を安全に止めよう。', 'ko': '9번 볼 가장자리를 1/16 두께로만 접촉하고, 가벼운 하단으로 수구를 안전하게 멈추세요.'},
    'efren_double_carom': {'en': 'Aim half of ball 4 with 62% power for optimal energy transfer to drive ball 8 into the pocket.', 'zh': '瞄准4号球半厚度，力度62%，产生最佳传力让8号球笔直滚向袋口。', 'ja': '4番球を半分狙い、力加減62%で8番球をポケットへ真っ直ぐ転がそう。', 'ko': '4번 볼의 절반을 조준하고 62%의 힘으로 샷하여 8번 볼을 포켓으로 직진시키세요.'},
    'efren_magic_mid_pocket': {'en': 'Squeeze ball 7 gently brushing the middle pocket rubber, with 45% power to prevent bouncing out.', 'zh': '挤压7号球微抚中袋胶边，力度45%避免反弹弹出。', 'ja': '7番球を中袋のゴムクッションに軽く擦らせ、弾き出されないよう力加減45%で撞こう。', 'ko': '7번 볼이 미드 포켓 고무를 살짝 스치도록 조준하고, 튕겨 나오지 않게 45%의 힘으로 치세요.'},
    'ronnie_max_follow': {'en': 'Push cue tip to the extreme top of cue ball (dy = -0.90) with high power (~78%) to accelerate forward after contact.', 'zh': '击球点推至母球最顶部 (dy = -0.90)，配合大力 (~78%) 使母球撞击后迅猛前冲。', 'ja': '手玉の最上部 (dy = -0.90) を捉え、強打 (~78%) で衝突後に手玉を一気に前進させよう。', 'ko': '팁 위치를 수구 최상단(dy = -0.90)으로 올리고 강한 힘(~78%)으로 밀어쳐 충돌 후 수구를 질주시키세요.'},
    'ronnie_left_hand_lightning': {'en': 'Strike center ball with 52% power, keeping the cue delivery rock-steady and straight.', 'zh': '击打母球正中心，力度52%，保持出杆绝对直线稳定无晃动。', 'ja': '手玉の中心を撞き、力加減52%でブレのない真っ直ぐなストロークを保とう。', 'ko': '수구 정중앙을 52%의 힘으로 치고, 흔들림 없이 곧은 큐 전달을 유지하세요.'},
    'ronnie_long_pot_crucible': {'en': 'Pinpoint aiming accuracy with 60% power; avoid English spin to keep trajectory perfectly true.', 'zh': '绝对精准瞄准，力度60%，不要加任何旋转塞以防轨迹漂移。', 'ja': '狙いを完璧に合わせ、力加減60%、軌道がブレないようひねりは使わずに撞こう。', 'ko': '정확한 조준, 60%의 힘, 궤적이 빗나가지 않도록 회전 없이 정타로 치세요.'},
    'ronnie_cluster_break': {'en': '75% power with moderate follow (dy = -0.45) so cue ball drives through ball 3 into the cluster pack.', 'zh': '力度75%配合轻高杆 (dy = -0.45)，使母球推入3号球后直接冲散目标球堆。', 'ja': '力加減75%に軽いフォロー (dy = -0.45) を加え、3番球を押した後に球群へ突入させよう。', 'ko': '75%의 힘과 약간의 상단(dy = -0.45)으로 3번 볼을 넣은 후 수구를 공 뭉치로 돌진시키세요.'},
    'ronnie_gap_sniper': {'en': 'Aim directly at the bullseye of the needle gap with 58% power and steady hands.', 'zh': '精准瞄准缝隙靶心，力度58%，出杆平稳不抖手。', 'ja': '隙間の中心を正確に狙い、手ブレなく力加減58%で撞こう。', 'ko': '틈새 중심을 정확히 겨냥하고, 흔들림 없이 58%의 힘으로 스트로크하세요.'},
    'ronnie_seventh_world_crown': {'en': '15-degree thin cut with 68% power, combined with gentle draw to hold cue ball position.', 'zh': '15度薄切，力度68%，结合轻微低杆回拉以控住母球。', 'ja': '15度の薄切り、力加減68%、軽い引きを組み合わせて手玉をキープしよう。', 'ko': '15도 얇은 컷, 68%의 힘, 가벼운 하단 끌어치기를 결합하여 수구를 유지하세요.'},
    'shane_super_draw': {'en': 'Lower cue tip to bottom of cue ball (dy = 0.85 - 1.0) with >80% power for spectacular draw back.', 'zh': '击球点拉至母球底部 (dy = 0.85 - 1.0)，出杆力度80%以上，碰撞后实现惊人急速后退。', 'ja': '手玉の最下部 (dy = 0.85 - 1.0) を捉え、力加減80%以上で衝突後に劇的な引き戻しを決めよう。', 'ko': '팁 위치를 수구 최하단(dy = 0.85 - 1.0)으로 내리고 80% 이상의 힘으로 쳐 충돌 후 놀라운 백스핀을 만드세요.'},
    'shane_break_sniper': {'en': '85% power, aiming directly through the center of mass of ball 1.', 'zh': '力度85%，直接穿心瞄准1号球重心。', 'ja': '力加減85%、1番球の重心を真っ直ぐ狙おう。', 'ko': '85%의 힘으로 1번 볼의 무게중심을 정면으로 겨냥하세요.'},
    'shane_jump_combo': {'en': '78% power, with slight draw to assist a clean, smooth hop over the obstacle.', 'zh': '力度78%，轻微低杆辅助让母球顺畅跳跃过障。', 'ja': '力加減78%、軽い引きを加えてスムーズなジャンプをサポートしよう。', 'ko': '78%의 힘, 가벼운 하단을 주어 부드러운 장애물 도약을 유도하세요.'},
    'shane_dead_angle_cut': {'en': 'Cut outer edge of ball 4 with 52% power and subtle outside English.', 'zh': '切4号球外边缘，力度52%，配合微量顺塞外旋。', 'ja': '4番球の外側エッジを薄切りし、力加減52%にわずかな外ひねりを加えよう。', 'ko': '4번 볼 바깥 가장자리를 깎고, 52%의 힘과 미세한 바깥쪽 회전을 결합하세요.'},
    'shane_position_freeze': {'en': 'Center ball stun shot with exactly measured 48% power to freeze on the spot.', 'zh': '击打母球中心定杆 (Stun shot)，力度精准控制在48%。', 'ja': '手玉中心のスタンショット、過不足のない48%の力でその場に止めよう。', 'ko': '수구 정중앙 스턴 샷으로 적절한 48%의 힘으로 정확히 그 자리에 멈추세요.'},
    'shane_world_9ball_champion': {'en': 'Thin cut on ball 9 edge with 62% power and slight draw (dy = 0.30) for cue ball control.', 'zh': '薄切9号球边缘，力度62%，微低杆 dy = 0.30 精确掌控走位。', 'ja': '9番球のエッジを薄く狙い、力加減62%、微小な引き dy = 0.30 で手玉をコントロールしよう。', 'ko': '9번 볼 가장자리를 얇게 겨냥하고, 62%의 힘과 가벼운 하단(dy = 0.30)으로 큐볼을 제어하세요.'},
    'venom_masse_curve': {'en': 'Extreme right English (dx = 0.85, dy = 0.55) with strong snap power to curve dramatically around blockers.', 'zh': '强烈极右塞 (dx = 0.85, dy = 0.55) 结合低杆爆发力，划出惊天大弧线绕过障碍。', 'ja': '極端な右ひねり (dx = 0.85, dy = 0.55) と強打を組み合わせ、劇的なカーブで障害球を回り込もう。', 'ko': '극한의 우측 회전 (dx = 0.85, dy = 0.55)과 강한 스냅으로 장애물을 크게 감아 도는 커브를 만드세요.'},
    'venom_tunnel_shot': {'en': 'Aim dead-center down the midline with 55% power and zero spin.', 'zh': '精准瞄准中心线，力度55%，不带任何旋转。', 'ja': '中心線を正確に狙い、ひねりを使わずに力加減55%で真っ直ぐ撞こう。', 'ko': '중심선을 정확히 겨냥하고, 회전 없이 55%의 힘으로 곧게 치세요.'},
    'venom_butterfly_split': {'en': 'Aim right at the split angle between two balls with 68% power.', 'zh': '瞄准双球接触缝隙正中，出杆力度68%。', 'ja': '2つの球の接触角の真ん中を狙い、力加減68%で撞こう。', 'ko': '두 공의 접촉각 정중앙을 겨냥하고 68%의 힘으로 스트로크하세요.'},
    'hoang_sao_clutch': {'en': 'Razor-thin cut tangent on ball 8 with subtle draw (dy ~ 0.4) and 50% power.', 'zh': '切8号球极薄切线，结合微低杆 (dy ~ 0.4) 和适度力量 (50%) 确保球入底袋。', 'ja': '8番球の極薄接線を狙い、軽い引き (dy ~ 0.4) と力加減50%で下部コーナーへ落とそう。', 'ko': '8번 볼의 극도로 얇은 접선을 겨냥하고, 약간의 하단(dy ~ 0.4)과 50%의 힘으로 코너에 넣으세요.'},
    'hoang_sao_soft_touch': {'en': 'Ultra-gentle 38% power, striking pure center of cue ball for whisper-soft glide.', 'zh': '极柔和力度38%，击打母球绝对正中心以求轻盈滑动。', 'ja': '極めてソフトな力加減38%、手玉の完全中心を撞いて優しく転がそう。', 'ko': '38%의 극도로 부드러운 힘으로 수구 정중앙을 쳐서 부드럽게 굴려 보내세요.'},
    'hoang_sao_scottish_champion': {'en': 'Thin cut on 9 at difficult angle with 66% power and an iron-steady stroke.', 'zh': '在刁钻角度下薄切9号球，力度66%，手握球杆稳如磐石。', 'ja': '厳しい角度から力加減66%で9番球を薄切りし、鉄のようにブレないストロークを保とう。', 'ko': '까다로운 각도에서 66%의 힘으로 9번 볼을 얇게 깎고, 강철처럼 흔들림 없는 스트로크를 유지하세요.'},
    'earl_combo_jump': {'en': 'Aim exact contact point between cue ball and ball 3 with 55% power and zero spin.', 'zh': '瞄准母球与3号球接触切点，力度55%不带旋转直入狭缝。', 'ja': '手玉と3番球の接触点を正確に狙い、ひねりなし力加減55%で狭い隙間へ真っ直ぐ通そう。', 'ko': '수구와 3번 볼의 접촉점을 정확히 겨냥하고 회전 없이 55%의 힘으로 틈새를 뚫으세요.'},
    'earl_short_jump': {'en': 'Elevate cue to 45 degrees with 72% jump power and light draw assist.', 'zh': '球杆抬高45度，跳球弹跳力72%，轻微低杆辅助弹起。', 'ja': 'キューを45度に立て、跳躍力72%で軽い引きを加えて障害を飛び越えよう。', 'ko': '큐를 45도로 세우고 72%의 점프 파워와 가벼운 하단 회전으로 장애물을 뛰어넘으세요.'},
    'earl_rail_speed': {'en': '78% crisp power brushing the outer edge of ball 4 along rail.', 'zh': '78%干脆力量，紧抚4号球外边缘顺库滑行。', 'ja': '力加減78%の鋭いストロークで、4番球の外縁を擦ってレールを走らせよう。', 'ko': '78%의 파워로 4번 볼 바깥쪽을 스쳐 쿠션을 따라 질주시킵니다.'},
    'earl_power_breakthrough': {'en': 'Heavy 82% power smash through half of ball 2.', 'zh': '强力82%暴击，吃透2号球半球厚度突破残局。', 'ja': '力加減82%の強打で2番球を半分捉えて打ち破ろう。', 'ko': '82%의 강력한 힘으로 2번 볼의 절반을 강타하여 돌파하세요.'},
    'earl_hurricane_run': {'en': 'Razor 1/8th thin cut with 62% power.', 'zh': '薄切1/8球厚度，出杆力度62%。', 'ja': '1/8の薄切り、力加減62%で正確に撞こう。', 'ko': '1/8 두께로 얇게 깎고 62%의 힘으로 치세요.'},
    'earl_championship_jump': {'en': 'Cue elevation 50 degrees with 80% snap power aimed squarely at ball 9.', 'zh': '杆角50度，爆发力80%，瞄准9号球核心。', 'ja': 'キュー角度50度、跳躍力80%で9番球の中心を狙おう。', 'ko': '큐 각도 50도, 80%의 점프 탄력으로 9번 볼의 중심을 조준하세요.'},
    'bustamante_narrow_breach': {'en': 'Aim precisely along the inner edge with 60% power.', 'zh': '瞄准内边缘极其狭窄处，出杆力度60%。', 'ja': '内側エッジを正確に狙い、力加減60%で隙間を通そう。', 'ko': '안쪽 가장자리를 정밀하게 조준하고 60%의 힘으로 스트로크하세요.'},
    'bustamante_carom_deflect': {'en': 'Aim 1/3 thickness of ball 4 with 55% power.', 'zh': '瞄准4号球1/3厚度，击球力度55%。', 'ja': '4番球の1/3の厚みを狙い、力加減55%でコースを変えよう。', 'ko': '4번 볼의 1/3 두께를 겨냥하고 55%의 힘으로 치세요.'},
    'bustamante_courageous_cut': {'en': 'Absolute razor cut on ball 8 edge with 56% power and an unwavering hand.', 'zh': '绝对极限薄切8号球边缘，力度56%，出杆无比坚定。', 'ja': '8番球のエッジを極限まで薄切り、力加減56%で迷わず撞こう。', 'ko': '8번 볼의 극도로 얇은 가장자리를 56%의 힘과 흔들림 없는 손으로 깎아내세요.'},
    'shaw_frontal_assault': {'en': '68% power with dead-aim accuracy into the blind corner.', 'zh': '出杆力度68%，死角直线精确瞄准不抖手。', 'ja': '力加減68%、手ブレなく死角を真っ直ぐ狙おう。', 'ko': '68%의 힘으로 사각지대를 향해 흔들림 없이 정타로 샷하세요.'},
    'shaw_barrier_punch': {'en': 'Maximum tension 85% power with a laser-straight cue follow.', 'zh': '极限紧绷力度85%，保持球杆绝对笔直贯穿。', 'ja': '超強打85%、キューを完璧に真っ直ぐ押し出そう。', 'ko': '85%의 최대 파워로 큐를 레이저처럼 곧게 관통시키세요.'},
    'shaw_eagle_jump': {'en': '45-degree cue angle with 76% jump bounce power.', 'zh': '球杆角度45度，跳球弹跳力76%。', 'ja': 'キュー角度45度、跳躍力76%で飛び越えよう。', 'ko': '큐 각도 45도, 76%의 탄력으로 장애물을 넘기세요.'},
    'shaw_century_run': {'en': 'Precision 1/16th tangent contact with 64% power.', 'zh': '精准接球外切线1/16薄度，出杆力度64%。', 'ja': '1/16の極薄接線を狙い、力加減64%でストロークしよう。', 'ko': '1/16 접선에 정밀하게 접촉하고 64%의 힘으로 치세요.'},
    'gorst_sniper_cut': {'en': 'Zero English spin, 62% power, aiming outer tangent edge of ball 1.', 'zh': '不加任何旋转塞，力度62%，精切1号球外侧切线。', 'ja': 'ひねりゼロ、力加減62%、1番球の外側接線を狙おう。', 'ko': '회전 없이 62%의 힘으로 1번 볼 외곽 접선을 노리세요.'},
    'gorst_death_corner_snooker': {'en': 'Smooth 42% power with light draw control to lock cue ball.', 'zh': '柔顺力度42%，轻微低杆回控以锁死母球。', 'ja': '滑らかな力加減42%、軽い引きで手玉を死角に封じ込めよう。', 'ko': '부드러운 42%의 힘과 가벼운 하단으로 수구를 봉쇄하세요.'},
    'gorst_world_crown_ghost': {'en': '1/16th razor cut with 65% power and absolute ice-cold composure.', 'zh': '1/16极限极薄切，力度65%，保持绝对绝对冷静。', 'ja': '1/16の極薄カット、力加減65%、氷のように冷静に撞こう。', 'ko': '1/16 면도날 컷, 65%의 힘, 냉정하고 차분하게 스트로크하세요.'},
    'blomdahl_double_carom_pot': {'en': 'Aim half-ball thickness of ball 4 with 62% power.', 'zh': '瞄准4号球半厚度，出杆力度62%。', 'ja': '4番球の半分の厚みを狙い、力加減62%で撞こう。', 'ko': '4번 볼의 절반 두께를 조준하고 62%의 힘으로 치세요.'},
    'blomdahl_maestro_masterpiece': {'en': '3 cushions narrow angle rebound, English dx = 0.65, 80% power.', 'zh': '窄角三库大折射，加塞 dx = 0.65，出杆力度80%。', 'ja': '狭角3クッション、ひねり dx = 0.65、力加減80%で撞こう。', 'ko': '협각 3쿠션 리바운드, 회전 dx = 0.65, 80%의 힘으로 치세요.'},
    'sayginer_jump_cushion_press': {'en': '45-degree cue elevation with draw spin dy = 0.50 and 75% power.', 'zh': '球杆抬高45度，低杆旋转 dy = 0.50，力度75%。', 'ja': 'キュー角度45度、引きスピン dy = 0.50、力加減75%でクッションを叩こう。', 'ko': '큐 각도 45도, 하단 회전 dy = 0.50, 75%의 힘으로 쿠션을 압박하세요.'},
    'sayginer_pearl_chain': {'en': '72% power with side spin dx = 0.45 for domino carom momentum.', 'zh': '力度72%配合侧塞 dx = 0.45 触发连环借力。', 'ja': '力加減72%、サイドスピン dx = 0.45 で連鎖衝突を引き起こそう。', 'ko': '72%의 힘과 측면 회전 dx = 0.45로 연쇄 충돌을 유도하세요.'},
    'ceulemans_classic_diamond': {'en': 'Align precisely with 3rd diamond marker on rail, English dx = 0.50, 68% power.', 'zh': '精确对准台边第3颗钻石点位，加塞 dx = 0.50，力度68%。', 'ja': 'レールの3番目のダイヤモンドマークに正確に合わせ、ひねり dx = 0.50、力加減68%で撞こう。', 'ko': '레일의 3번째 다이아몬드 포인트에 정확히 조준하고, 회전 dx = 0.50, 68%의 힘으로 치세요.'},
    'ceulemans_classic_corner_bank': {'en': '62% power with subtle draw dy = 0.20 for textbook angle reflection.', 'zh': '出杆力度62%，轻微低杆 dy = 0.20 实现教科书级反射角。', 'ja': '力加減62%、微小な引き dy = 0.20 で教科書通りの角度を再現しよう。', 'ko': '62%의 힘과 미세한 하단 dy = 0.20으로 교과서적인 각도를 만드세요.'},
    'ceulemans_soft_center_glide': {'en': 'Whisper-soft 40% power, maintaining a stable cue follow with zero wobble.', 'zh': '轻盈力度40%，保持出杆绝对平稳无抖动。', 'ja': '非常に滑らかな力加減40%、手ブレなく安定して押し出そう。', 'ko': '40%의 부드러운 힘으로 흔들림 없이 안정적으로 밀어치세요.'},
    'ceulemans_lip_hanger_cut': {'en': 'Delicate 1/8th cut with 45% power to drop hanger gently.', 'zh': '细腻切入1/8球厚度，力度45%让悬球轻柔落袋。', 'ja': '1/8の厚みで繊細にカットし、力加減45%で優しく落とそう。', 'ko': '1/8 두께로 섬세하게 깎고 45%의 힘으로 부드럽게 떨어뜨리세요.'},
    'massey_behind_back_double': {'en': 'Align directly through center of ball 8 with 60% power and zero English.', 'zh': '直接瞄准8号球正中心，出杆力度60%不加任何侧塞。', 'ja': '8番球の中心を真っ直ぐ狙い、ひねりなし力加減60%で撞こう。', 'ko': '회전 없이 8번 볼의 중심을 직접 노리고 60%의 힘으로 치세요.'},
