  /// Lấy tiêu đề thế đánh huyền thoại theo ngôn ngữ
  static String getTitle(String id, String lang, String defaultText) {
    if (lang == 'vi') return defaultText;
    final byId = titles[id]?[lang];
    if (byId != null && byId.isNotEmpty) return byId;
    final byVi = titlesByVietnamese[defaultText]?[lang];
    if (byVi != null && byVi.isNotEmpty) return byVi;
    final enFallback = titles[id]?['en'] ?? titlesByVietnamese[defaultText]?['en'];
    if (enFallback != null && enFallback.isNotEmpty) return enFallback;
    return defaultText;
  }

  /// Lấy mô tả chi tiết thế đánh theo ngôn ngữ
  static String getDescription(String id, String lang, String defaultText) {
    if (lang == 'vi') return defaultText;
    final byId = descriptions[id]?[lang];
    if (byId != null && byId.isNotEmpty) return byId;
    final byVi = descriptionsByVietnamese[defaultText]?[lang];
    if (byVi != null && byVi.isNotEmpty) return byVi;
    final enFallback = descriptions[id]?['en'] ?? descriptionsByVietnamese[defaultText]?['en'];
    if (enFallback != null && enFallback.isNotEmpty) return enFallback;

    // Mẫu mô tả chuẩn xác với tên Master được dịch theo ngôn ngữ đích
    final masterKey = id.split('_').first;
    final masterName = masterNames[masterKey]?[lang] ?? masterNames[masterKey]?['en'] ?? getMasterName(defaultText, lang);
    return switch (lang) {
      'en' => 'Master trickshot by $masterName. Aim precisely, avoid obstacles, and pot the designated target ball into the target pocket!',
      'zh' => '$masterName 的大师绝技。精准瞄准，避开障碍球，将指定目标球稳稳送入目标袋口！',
      'ja' => '$masterName による名人の神技。正確に狙い、障害球を回避して指定の的球を目標ポケットに沈めよう！',
      'ko' => '$masterName의 전설적인 마스터 샷. 정밀하게 조준하고 장애물을 피해 지정된 목표구를 포켓에 넣으세요!',
      _ => defaultText,
    };
  }

  /// Lấy hướng dẫn kỹ thuật cơ thế đánh theo ngôn ngữ
  static String getHint(String id, String lang, String defaultText) {
    if (lang == 'vi') return defaultText;
    final byId = hints[id]?[lang];
    if (byId != null && byId.isNotEmpty) return byId;
    final byVi = hintsByVietnamese[defaultText]?[lang];
    if (byVi != null && byVi.isNotEmpty) return byVi;
    final enFallback = hints[id]?['en'] ?? hintsByVietnamese[defaultText]?['en'];
    if (enFallback != null && enFallback.isNotEmpty) return enFallback;

    // Trích xuất hướng dẫn kỹ thuật từ từ khóa defaultText
    final lower = defaultText.toLowerCase();
    if (lower.contains('nhảy') || lower.contains('jump')) {
      return switch (lang) {
        'en' => 'Elevate cue angle ~45-50°, strike firmly with snappy follow-through to jump over the obstacle ball.',
        'zh' => '抬高球杆约 45-50 度，手腕发力短促有力，使母球利落跳跃越过障碍球。',
        'ja' => 'キュー角度を約45〜50度に立て、手首のスナップを効かせて障害球を飛び越えよう。',
        'ko' => '큐 각도를 약 45-50도로 세우고, 손목 스냅을 살려 장애구를 뛰어넘도록 스트로크하세요.',
        _ => defaultText,
      };
    }
    if (lower.contains('cắt') || lower.contains('mỏng')) {
      return switch (lang) {
        'en' => 'Aim for a delicate razor-thin contact on the object ball edge with smooth, controlled speed.',
        'zh' => '精确瞄准目标球的极薄边缘，以平稳细腻的杆速完成薄切落袋。',
        'ja' => '的球の極薄エッジを繊細に狙い、滑らかで安定した力加減でストロークしよう。',
        'ko' => '목표구의 극도로 얇은 에지를 섬세하게 조준하고 부드러운 속도로 스트로크하세요.',
        _ => defaultText,
      };
    }
    if (lower.contains('băng') || lower.contains('bank') || lower.contains('kick')) {
      return switch (lang) {
        'en' => 'Calculate cushion incident and reflection angles precisely, using steady medium power.',
        'zh' => '精密计算吃库入射角与反射角，以稳定的中等力度出杆翻袋/解球。',
        'ja' => 'クッションの入射角と反射角を正確に計算し、安定した中等度の力で撞こう。',
        'ko' => '쿠션 입사각과 반사각을 정밀하게 계산하고 안정적인 중간 힘으로 샷을 실행하세요.',
        _ => defaultText,
      };
    }
    if (lower.contains('trô') || lower.contains('kéo')) {
      return switch (lang) {
        'en' => 'Use bottom draw spin with firm stroke to control the cue ball return path.',
        'zh' => '使用低杆拉杆配合坚决出杆，精确控制母球回撤轨迹。',
        'ja' => '下スピン（ドロー）を効かせて手玉の戻り軌道をコントロールしよう。',
        'ko' => '하단 스핀(끌어치기)을 사용하여 수구의 복귀 궤적을 제어하세요.',
        _ => defaultText,
      };
    }
    if (lower.contains('cu-lê') || lower.contains('tiến') || lower.contains('đẩy')) {
      return switch (lang) {
        'en' => 'Apply high topspin follow to drive the cue ball forward off cushions.',
        'zh' => '使用高杆推杆顺势走位，让母球顺畅吃库跑位。',
        'ja' => '上スピン（フォロー）でクッション反発後も力強く前進させよう。',
        'ko' => '상단 스핀(밀어치기)을 주어 쿠션 반발 후에도 수구를 힘차게 전진시키세요.',
        _ => defaultText,
      };
    }
    if (lower.contains('áp-phê') || lower.contains('xoáy') || lower.contains('massé')) {
      return switch (lang) {
        'en' => 'Use lateral English (side spin) to widen or sharpen the rebound angle off rails.',
        'zh' => '使用侧塞（左/右旋转）调整库边反弹角度。',
        'ja' => 'サイドスピン（ひねり）を使ってレールからの反発角度を調整しよう。',
        'ko' => '사이드 스핀(회전)을 주어 쿠션 반사각을 원하는 각도로 조절하세요.',
        _ => defaultText,
      };
    }

    return switch (lang) {
      'en' => 'Align the cue stick carefully with moderate power for high precision.',
      'zh' => '仔细校准击球瞄准线，以适度平稳的力度出杆。',
      'ja' => '狙い線を慎重に合わせ、適切な力加減で正確にストロークしよう。',
      'ko' => '정밀하게 조준선을 맞추고 적절한 힘으로 샷을 실행하세요.',
      _ => defaultText,
    };
  }

  // --- GIẢI ĐẤU & NĂM THI ĐẤU ---
  static String getTournament(String id, String lang, String defaultText) {
    if (lang == 'vi') return defaultText;
    final lower = defaultText.toLowerCase();

    if (lower.contains('sands regency')) {
      return switch (lang) {
