    }

    if (RegExp(r'^[A-Za-z0-9\s\-\.\(\)]+\$').hasMatch(defaultText)) {
      if (lang == 'en') return defaultText;
    }

    return switch (lang) {
      'en' => 'Legendary Billiard Master Tournament',
      'zh' => '世界台球传奇大师赛',
